 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    # The full-color row is the fixed barrier; objects fall toward it.
    barrier = next((r for r, row in enumerate(grid) if all(v != 0 for v in row)), None)
    if barrier is None:
        return [row[:] for row in grid]
    direction = -1 if barrier < h // 2 else 1
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or r == barrier or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color and ny != barrier:
                        seen.add((ny,nx)); q.append((ny,nx))
            components.append((color, cells))
    out = [[0] * w for _ in range(h)]
    out[barrier] = grid[barrier][:]
    # Move components closest to the barrier first so later pieces stack behind them.
    components.sort(key=lambda item: min(y for y, x in item[1]), reverse=(direction > 0))
    for color, cells in components:
        cells = list(cells)
        while True:
            shifted = [(y + direction, x) for y, x in cells]
            if any(y < 0 or y >= h or x < 0 or x >= w or out[y][x] != 0 for y, x in shifted):
                break
            cells = shifted
        for y, x in cells:
            out[y][x] = color
    return out
